html,body{height:auto!important;min-height:0!important}
html{-webkit-text-size-adjust:100%}
body{margin:0;padding:2px;background:transparent;color:var(--text-primary);font:16px/1.7 var(--font-sans)}
body.capcom-card{padding:16px}
@media (max-width:479px){body.capcom-card{padding:8px}}
body.capcom-card>svg{display:block;max-width:100%}
body.capcom-card>svg[viewBox]{height:auto}
h1,h2,h3{font-weight:500}
h1{font-size:22px}
h2{font-size:18px}
h3{font-size:16px}
a{color:var(--text-accent)}
code,kbd,pre,samp{font-family:var(--font-mono);font-size:var(--font-size-code)}
img,video,canvas,svg{max-width:100%}
.sr-only{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap;border:0}
.ti{font-family:"tabler-icons";font-style:normal;font-weight:normal;line-height:1;text-transform:none;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}
:where(button,input[type=button],input[type=submit],input[type=reset]){box-sizing:border-box;padding:var(--pad-sm) var(--pad-md);border:1px solid var(--border-strong);border-radius:var(--radius);background:transparent;color:inherit;font:inherit;font-size:var(--font-size-body);line-height:1.35;cursor:pointer;transition:background-color var(--dur-fast),transform var(--dur-fast)}
:where(button:hover,input[type=button]:hover,input[type=submit]:hover,input[type=reset]:hover){background:var(--fill-secondary)}
:where(button:active,input[type=button]:active,input[type=submit]:active,input[type=reset]:active){transform:scale(.98)}
:where(button:focus-visible,input[type=button]:focus-visible,input[type=submit]:focus-visible,input[type=reset]:focus-visible){outline:none;border-color:var(--border-stronger);box-shadow:var(--focus-shadow)}
